-- ---------------------------------------------------------------------------
-- Seed das pessoas do painel CAC — a planilha "dados pessoais" de 17/08/2026.
--
-- `on conflict do nothing`: rodar de novo não desfaz edição feita na tela.
--
-- A normalização do CNPJ acontece aqui porque a planilha vem suja — tem CPF de
-- 11 dígitos, tem "50.562.257-0001/05" com a barra no lugar errado e tem
-- espaço à esquerda. Todos viram os mesmos dígitos, que é a chave de casamento
-- com `cCPFCNPJCliente` do Omie.
--
-- OS ACENTOS IMPORTAM. "Liderança OPS" e "Branding e Conteúdo" são os nomes que
-- as regras de `cac_linhas` procuram em `departamentos`; gravar sem acento faz
-- a linha do painel devolver zero calada, porque a comparação é literal.
-- ---------------------------------------------------------------------------

insert into public.cac_pessoas (cnpj, nome, departamento, categoria_omie, remuneracao, planilha_comissao)
select regexp_replace(v.cnpj, '[^0-9]', '', 'g'), v.nome, v.departamento, v.categoria, v.remuneracao, nullif(btrim(v.planilha), '')
from (values
